"""DS4 fused decode-glue Triton kernels (gfx1151).

Hand-fused replacements for small aten kernel chains on the decode path.
Every kernel here is BIT-EXACT vs the aten chain it replaces. Each call site
is env-gated (DS4_FUSE_*, default ON) and falls back to the stock chain on
any unsupported shape/dtype.

Chains covered:
- silu_mul_clamp: SiluAndMulWithClamp.forward_native
    clamp(gate) / clamp(up) / silu / mul  (4 kernels) -> 1 kernel.
- gather_dequant_pad: ds4_tl_indexer.fp8_paged_mqa_logits_tl decode gather
    paged-cache index-gather + fp8->bf16 value copy + fp32 scale copy +
    zero-pad to the KV bucket (5 kernels, ~3x the cache bytes) -> 1 kernel
    reading the paged cache once.
- topk_ragged_decode: rocm.py compute_global_topk_ragged_indices_and_indptr
    lens kernel + zeros + cumsum + pack kernel (4 kernels) -> 1 kernel
    (single program; decode has <= a few dozen rows).
"""

import torch

from vllm.triton_utils import tl, triton

# ---------------------------------------------------------------------------
# F1: fused clamp/clamp/silu/mul (SiluAndMulWithClamp.forward_native)
# ---------------------------------------------------------------------------
#
# aten semantics reproduced exactly:
#   gate = clamp(x[..., :d], max=limit)         (opmath fp32, exact select)
#   up   = clamp(x[..., d:], -limit, limit)
#   s    = silu(gate) = gate * sigmoid(gate)    (fp32 math, ONE round to bf16)
#   out  = s * up                               (fp32 mult, ONE round to bf16)
# NaN propagation matches torch.clamp (comparisons false -> value kept).


@triton.jit
def _silu_mul_clamp_kernel(
    x_ptr,
    out_ptr,
    n_elem,
    d,
    limit,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elem
    row = offs // d
    col = offs % d
    g = tl.load(x_ptr + row * (2 * d) + col, mask=mask, other=0.0)
    u = tl.load(x_ptr + row * (2 * d) + d + col, mask=mask, other=0.0)
    gf = g.to(tl.float32)
    uf = u.to(tl.float32)
    # torch.clamp semantics (NaN propagates: comparison False keeps x)
    gf = tl.where(gf > limit, limit, gf)
    uf = tl.where(uf > limit, limit, uf)
    uf = tl.where(uf < -limit, -limit, uf)
    # silu in fp32, single round to bf16 (matches aten::silu on bf16)
    s = (gf * tl.sigmoid(gf)).to(tl.bfloat16)
    # final mul: bf16 operands upcast to fp32, single round (matches aten::mul)
    o = (s.to(tl.float32) * uf).to(tl.bfloat16)
    tl.store(out_ptr + offs, o, mask=mask)


def silu_mul_clamp(x: torch.Tensor, limit: float) -> torch.Tensor | None:
    """Fused SiluAndMulWithClamp for 2D bf16 contiguous inputs.

    Returns None when the input is not eligible (caller falls back to the
    stock aten chain).
    """
    if x.dtype is not torch.bfloat16 or x.dim() != 2 or not x.is_contiguous():
        return None
    n, dd = x.shape
    d = dd // 2
    if d * 2 != dd or n == 0:
        return None
    out = torch.empty((n, d), dtype=x.dtype, device=x.device)
    n_elem = n * d
    BLOCK = 1024
    _silu_mul_clamp_kernel[(triton.cdiv(n_elem, BLOCK),)](
        x, out, n_elem, d, float(limit), BLOCK=BLOCK
    )
    return out


# ---------------------------------------------------------------------------
# F2: fused paged-cache gather + fp8->bf16 dequant-cast + scale copy + pad
# ---------------------------------------------------------------------------
#
# Replaces (per row group, per indexer layer, decode):
#   cache = flat[block_tables[gi, :npg]]                       (aten::index)
#   cv = cache[..., :so].view(fp8).to(bf16).view(psl, dim)[:gsl].contiguous()
#   cs = cache[..., so:].view(f32).contiguous().view(psl)[:gsl].contiguous()
#   cv = F.pad(cv, (0, 0, 0, gslk - gsl)); cs = F.pad(cs, (0, gslk - gsl))
# with one kernel that reads the paged cache exactly once and writes the
# padded cv/cs directly. fp8(e4m3)->bf16 is value-exact; scales are bitwise
# fp32 copies; pad rows are exact zeros -> bit-exact by construction (still
# validated vs the aten chain).


@triton.jit
def _gather_dequant_pad_kernel(
    flat_ptr,  # uint8 paged cache, rows of >= bs*(dim+4) bytes (aligned)
    bt_ptr,  # int32/int64 page ids for this row group [npg]
    cv_ptr,  # bf16 out [gslk, dim]
    cs_ptr,  # fp32 out [gslk]
    gsl,
    row_bytes,  # flat.stride(0): may exceed bs*(dim+4) (576B page alignment)
    bs: tl.constexpr,
    dim: tl.constexpr,
    FP8_FNUZ: tl.constexpr,
):
    pos = tl.program_id(0)
    dofs = tl.arange(0, dim)
    if pos < gsl:
        page = tl.load(bt_ptr + pos // bs).to(tl.int64)
        slot = pos % bs
        base = page * row_bytes
        raw = tl.load(flat_ptr + base + slot * dim + dofs)
        if FP8_FNUZ:
            v = raw.to(tl.float8e4b8, bitcast=True).to(tl.bfloat16)
        else:
            v = raw.to(tl.float8e4nv, bitcast=True).to(tl.bfloat16)
            # triton's e4m3fn cast saturates 0x7f/0xff to 480 instead of NaN;
            # torch maps them to bf16 0x7ff0 / 0xfff0. Match torch bitwise.
            is_nan = (raw & 0x7F) == 0x7F
            nanbits = (0x7FF0 | ((raw.to(tl.uint16) & 0x80) << 8)).to(tl.uint16)
            v = tl.where(is_nan, nanbits.to(tl.bfloat16, bitcast=True), v)
        # per-token fp32 scale, assembled from its 4 little-endian bytes (the
        # cache view is NOT 4-byte reinterpretable: aligned row strides).
        sofs = tl.arange(0, 4)
        sraw = tl.load(flat_ptr + base + bs * dim + slot * 4 + sofs).to(tl.uint32)
        sbits = tl.sum(sraw << (8 * sofs))
        s = sbits.to(tl.float32, bitcast=True)
        tl.store(cv_ptr + pos * dim + dofs, v)
        tl.store(cs_ptr + pos, s)
    else:
        tl.store(cv_ptr + pos * dim + dofs, tl.zeros([dim], dtype=tl.bfloat16))
        tl.store(cs_ptr + pos, 0.0)


def gather_dequant_pad(
    flat: torch.Tensor,  # [num_pages, bs*(dim+4)] uint8
    bt_row: torch.Tensor,  # [>=npg] page ids (one row of block_tables)
    npg: int,
    gsl: int,
    gslk: int,
    bs: int,
    dim: int,
    fp8_fnuz: bool,
) -> tuple[torch.Tensor, torch.Tensor]:
    assert flat.stride(1) == 1
    cv = torch.empty((gslk, dim), dtype=torch.bfloat16, device=flat.device)
    cs = torch.empty((gslk,), dtype=torch.float32, device=flat.device)
    _gather_dequant_pad_kernel[(gslk,)](
        flat,
        bt_row,
        cv,
        cs,
        gsl,
        flat.stride(0),
        bs=bs,
        dim=dim,
        FP8_FNUZ=fp8_fnuz,
    )
    return cv, cs


# ---------------------------------------------------------------------------
# F4: fused decode topk ragged build (lens + indptr + pack in one launch)
# ---------------------------------------------------------------------------
#
# Replaces compute_global_topk_ragged_indices_and_indptr's 4 launches
# (_compute_topk_lens_kernel, zeros, cumsum, _pack_global_topk_ragged_kernel)
# with ONE single-program kernel. Decode has num_tokens <= ~a few dozen and
# topk = 512, so a single workgroup covers the whole problem. All integer
# arithmetic -> bit-exact.


@triton.jit
def _topk_ragged_decode_kernel(
    topk_indices_ptr,
    topk_stride,
    is_valid_ptr,
    t2r_ptr,
    block_table_ptr,
    bt_stride,
    lens_ptr,
    indptr_ptr,
    ragged_ptr,
    num_tokens,
    block_size,
    topk: tl.constexpr,
    TOPK_PAD: tl.constexpr,
):
    # single program: grid == (1,)
    offs = tl.arange(0, TOPK_PAD)
    omask = offs < topk
    running = tl.zeros((), dtype=tl.int32)
    tl.store(indptr_ptr + 0, 0)
    for t in range(0, num_tokens):
        idx = tl.load(
            topk_indices_ptr + t * topk_stride + offs, mask=omask, other=-1
        )
        valid_tok = tl.load(is_valid_ptr + t)
        cnt = tl.sum((idx >= 0).to(tl.int32), axis=0)
        cnt = tl.where(valid_tok != 0, cnt, 0)
        tl.store(lens_ptr + t, cnt)
        # pack: same layout as the stock pack kernel (offset < out_len)
        out_len = cnt
        req = tl.load(t2r_ptr + t)
        pmask = omask & (offs < out_len)
        vald = pmask & (idx >= 0)
        bidx = idx // block_size
        bnum = tl.load(
            block_table_ptr + req * bt_stride + bidx, mask=vald, other=0
        )
        slot = tl.where(vald, bnum * block_size + idx % block_size, -1)
        tl.store(ragged_ptr + running + offs, slot, mask=pmask)
        running = running + cnt
        tl.store(indptr_ptr + t + 1, running)


def topk_ragged_decode(
    topk_indices: torch.Tensor,  # [num_tokens, topk] int32 contiguous
    token_to_req_indices: torch.Tensor,
    block_table: torch.Tensor,
    block_size: int,
    is_valid_token: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    num_tokens, topk = topk_indices.shape
    dev = topk_indices.device
    lens = torch.empty(num_tokens, dtype=torch.int32, device=dev)
    indptr = torch.empty(num_tokens + 1, dtype=torch.int32, device=dev)
    ragged = torch.empty(num_tokens * topk, dtype=torch.int32, device=dev)
    _topk_ragged_decode_kernel[(1,)](
        topk_indices,
        topk_indices.stride(0),
        is_valid_token,
        token_to_req_indices,
        block_table,
        block_table.stride(0),
        lens,
        indptr,
        ragged,
        num_tokens,
        block_size,
        topk=topk,
        TOPK_PAD=triton.next_power_of_2(topk),
    )
    return ragged, indptr, lens


# ---------------------------------------------------------------------------
# F5: DSpark drafter in-graph glue fusions (all BIT-EXACT)
# ---------------------------------------------------------------------------
#
# The drafter's step-0 CUDA graph replays many tiny kernels; the rope /
# fp8-QAT / concat chains are pure elementwise glue whose GPU cost is almost
# entirely per-kernel dispatch. These kernels fuse each chain into ONE
# launch, reproducing the aten arithmetic bit-for-bit:
#   - complex rope mul: fp32 (x0*fr - x1*fi, x0*fi + x1*fr), single RNE
#     round to bf16 — matches torch's complex64 path (forward and
#     conjugate/inverse).
#   - fp8 QAT round-trip: per-64-block amax (exact max), clamp_min,
#     exp2(ceil(log2(amax/448))), clamp, fp32->e4m3fn RNE cast and back.
#   - passthrough/cat/scatter: pure data movement.
# The reductions that ARE order-dependent (q headwise mean, attention
# softmax) deliberately stay in aten. Gated by DS4_MTP_FUSE_GLUE (checked in
# dspark_mtp); these run inside the drafter's captured graph.

_DSPARK_HD: int = 512  # drafter kv latent width
_DSPARK_RD: int = 64  # rope tail width


@triton.jit
def _dspark_rope_cat_kernel(
    x_ptr,  # bf16 [rows, 512] contiguous (q or o, post-scale/post-cast)
    fr_ptr,  # complex64-as-float2 [rows // H, 32] contiguous
    out_ptr,  # bf16 [rows, 512]
    H: tl.constexpr,  # heads sharing one freqs row (1 for kv)
    INV: tl.constexpr,
    NOPE: tl.constexpr,  # 448
    RD2: tl.constexpr,  # 32 rope pairs
):
    row = tl.program_id(0)
    # passthrough of the first NOPE dims (exact copy); NOPE is not a power
    # of two, so use a padded masked range.
    no = tl.arange(0, 512)
    nm = no < NOPE
    tl.store(out_ptr + row * (NOPE + 2 * RD2) + no,
             tl.load(x_ptr + row * (NOPE + 2 * RD2) + no, mask=nm),
             mask=nm)
    p = tl.arange(0, RD2)
    base = row * (NOPE + 2 * RD2) + NOPE
    x0 = tl.load(x_ptr + base + 2 * p).to(tl.float32)
    x1 = tl.load(x_ptr + base + 2 * p + 1).to(tl.float32)
    frow = row // H
    fr = tl.load(fr_ptr + frow * 2 * RD2 + 2 * p)
    fi = tl.load(fr_ptr + frow * 2 * RD2 + 2 * p + 1)
    if INV:
        fi = -fi
    re = (x0 * fr - x1 * fi).to(tl.bfloat16)
    im = (x0 * fi + x1 * fr).to(tl.bfloat16)
    tl.store(out_ptr + base + 2 * p, re)
    tl.store(out_ptr + base + 2 * p + 1, im)


def dspark_rope_cat(x: torch.Tensor, fr: torch.Tensor, inverse: bool = False):
    """cat([x[..., :448], rope(x[..., 448:], fr)]) for bf16 x [..., H, 512]
    with fr complex64 [..., 32] broadcast over the head dim. Bit-exact vs
    torch.cat([x[..., :-64], _apply_rope(x[..., -64:], fr)], dim=-1)."""
    hd = x.shape[-1]
    rows = x.numel() // hd
    H = rows // (fr.numel() // 32)  # rows sharing one freqs row (heads)
    xc = x.reshape(rows, hd)
    assert xc.is_contiguous() and x.dtype == torch.bfloat16
    frv = torch.view_as_real(fr).reshape(-1, 64)
    assert frv.is_contiguous()
    out = torch.empty_like(xc)
    _dspark_rope_cat_kernel[(rows,)](
        xc, frv, out, H=H, INV=inverse, NOPE=hd - 64, RD2=32, num_warps=4
    )
    return out.view(x.shape)


@triton.jit
def _dspark_quant_rope_cat_kernel(
    x_ptr,  # bf16 [rows, 512], row stride x_stride (slices allowed)
    x_stride,
    fr_ptr,  # complex64-as-float2 [rows, 32]
    out_ptr,  # bf16 [rows, 512] contiguous
    QB: tl.constexpr,  # 64 quant block
    NQ: tl.constexpr,  # 7 quant blocks
    RD2: tl.constexpr,  # 32 rope pairs
):
    row = tl.program_id(0)
    qb = tl.arange(0, 8)[:, None]
    qm = qb < NQ
    qo = tl.arange(0, QB)[None, :]
    x = tl.load(x_ptr + row * x_stride + qb * QB + qo, mask=qm,
                other=0.0).to(tl.float32)
    amax = tl.maximum(tl.max(tl.abs(x), axis=1), 1e-4)  # [8] (pad rows inert)
    s = tl.math.exp2(tl.ceil(tl.math.log2(amax / 448.0)))[:, None]
    y = tl.clamp(x / s, -448.0, 448.0)
    y = y.to(tl.float8e4nv).to(tl.float32) * s
    hd: tl.constexpr = NQ * QB + 2 * RD2
    tl.store(out_ptr + row * hd + qb * QB + qo, y.to(tl.bfloat16), mask=qm)
    p = tl.arange(0, RD2)
    x0 = tl.load(x_ptr + row * x_stride + NQ * QB + 2 * p).to(tl.float32)
    x1 = tl.load(x_ptr + row * x_stride + NQ * QB + 2 * p + 1).to(tl.float32)
    fr = tl.load(fr_ptr + row * 2 * RD2 + 2 * p)
    fi = tl.load(fr_ptr + row * 2 * RD2 + 2 * p + 1)
    tl.store(out_ptr + row * hd + NQ * QB + 2 * p,
             (x0 * fr - x1 * fi).to(tl.bfloat16))
    tl.store(out_ptr + row * hd + NQ * QB + 2 * p + 1,
             (x0 * fi + x1 * fr).to(tl.bfloat16))


def dspark_quant_rope_cat(x: torch.Tensor, fr: torch.Tensor):
    """cat([act_quant_sim(x[..., :448]), rope(x[..., 448:], fr)]) for bf16
    x [..., 512] (last dim contiguous; row strides allowed), fr complex64
    one row of 32 per x row. Bit-exact vs the aten chain."""
    hd = x.shape[-1]
    rows = x.numel() // hd
    x2 = x.reshape(rows, hd)
    assert x2.stride(1) == 1 and x.dtype == torch.bfloat16
    frv = torch.view_as_real(fr).reshape(-1, 64)
    assert frv.is_contiguous() and frv.shape[0] == rows
    out = torch.empty((rows, hd), dtype=torch.bfloat16, device=x.device)
    _dspark_quant_rope_cat_kernel[(rows,)](
        x2, x2.stride(0), frv, out, QB=64, NQ=(hd - 64) // 64, RD2=32,
        num_warps=4,
    )
    return out.view(x.shape)


@triton.jit
def _dspark_insert_kv_kernel(
    kv0_ptr, kv1_ptr, kv2_ptr,  # bf16 [N, 512] rows (strides allowed)
    kv_stride,
    freqs_ptr,  # complex64-as-float2 [L, 32] full table
    slots_ptr,  # int [N] target positions (clamped >= 0 in-kernel)
    seq_slot_ptr,  # int [N]
    win_ptr,  # bf16 win_kv [n_stages, S, window, 512]
    win_s0, win_s1, win_s2,  # strides (elements) of win_kv dims 0..2
    window,
    QB: tl.constexpr,
    NQ: tl.constexpr,
    RD2: tl.constexpr,
):
    n = tl.program_id(0)
    stage = tl.program_id(1)
    kv_ptr = kv0_ptr
    if stage == 1:
        kv_ptr = kv1_ptr
    if stage == 2:
        kv_ptr = kv2_ptr
    slot_raw = tl.load(slots_ptr + n).to(tl.int64)
    # ring replicates torch's floored modulo + clamp_min(0):
    # (slots % window).clamp_min(0) -- torch % is floored (-1 % 128 == 127).
    ring = slot_raw % window
    ring = tl.where(ring < 0, ring + window, ring)
    ring = tl.maximum(ring, 0)
    # the freqs row uses clamp_min(0) on the raw slot (freqs_cis[slots.clamp_min(0)])
    slot = tl.maximum(slot_raw, 0)
    seq = tl.load(seq_slot_ptr + n).to(tl.int64)
    dst = win_ptr + stage * win_s0 + seq * win_s1 + ring * win_s2

    qb = tl.arange(0, 8)[:, None]
    qm = qb < NQ
    qo = tl.arange(0, QB)[None, :]
    x = tl.load(kv_ptr + n * kv_stride + qb * QB + qo, mask=qm,
                other=0.0).to(tl.float32)
    amax = tl.maximum(tl.max(tl.abs(x), axis=1), 1e-4)
    s = tl.math.exp2(tl.ceil(tl.math.log2(amax / 448.0)))[:, None]
    y = tl.clamp(x / s, -448.0, 448.0)
    y = y.to(tl.float8e4nv).to(tl.float32) * s
    tl.store(dst + qb * QB + qo, y.to(tl.bfloat16), mask=qm)

    p = tl.arange(0, RD2)
    x0 = tl.load(kv_ptr + n * kv_stride + NQ * QB + 2 * p).to(tl.float32)
    x1 = tl.load(kv_ptr + n * kv_stride + NQ * QB + 2 * p + 1).to(tl.float32)
    fr = tl.load(freqs_ptr + slot * 2 * RD2 + 2 * p)
    fi = tl.load(freqs_ptr + slot * 2 * RD2 + 2 * p + 1)
    tl.store(dst + NQ * QB + 2 * p, (x0 * fr - x1 * fi).to(tl.bfloat16))
    tl.store(dst + NQ * QB + 2 * p + 1, (x0 * fi + x1 * fr).to(tl.bfloat16))


def dspark_insert_kv(
    kvs: list[torch.Tensor],  # n_stages x bf16 [N, 512] (row strides allowed)
    freqs_cis: torch.Tensor,  # complex64 [L, 32]
    slots: torch.Tensor,  # [N]
    seq_slot: torch.Tensor,  # [N]
    win_kv: torch.Tensor,  # bf16 [n_stages, S, window, 512]
    window: int,
) -> None:
    """Fused insert_main_kv tail: per-stage QAT+rope (freqs gathered at
    clamp(slot,0), ring = clamp(slot,0) % window) scattered straight into the
    ring buffer. Bit-exact vs the stack/rope/quant/cat/index_put chain."""
    assert len(kvs) == 3
    N, hd = kvs[0].shape
    frv = torch.view_as_real(freqs_cis).reshape(freqs_cis.shape[0], 64)
    assert frv.is_contiguous() and win_kv.stride(3) == 1
    for kv in kvs:
        assert kv.stride(1) == 1 and kv.dtype == torch.bfloat16
        assert kv.stride(0) == kvs[0].stride(0)
    _dspark_insert_kv_kernel[(N, 3)](
        kvs[0], kvs[1], kvs[2], kvs[0].stride(0),
        frv, slots, seq_slot,
        win_kv, win_kv.stride(0), win_kv.stride(1), win_kv.stride(2),
        window,
        QB=64, NQ=(hd - 64) // 64, RD2=32, num_warps=4,
    )
